"use client";

import { useState } from "react";
import type { ContentPlanDetails } from "@/lib/arquiteto/contracts";
import { addOutlineSection, clonePlanDetails, moveOutlineSection, removeOutlineSection, updateOutlineSection, validateOutline } from "@/lib/planejador/outline";

const button = "inline-flex h-7 items-center rounded border border-indigo-900 bg-indigo-950/20 px-2.5 text-[10px] font-bold text-indigo-300 hover:bg-indigo-950/50 disabled:cursor-not-allowed disabled:opacity-40";
const input = "mt-1 h-8 w-full rounded border border-slate-800 bg-black px-2 text-[10px] text-slate-200 outline-none focus:border-indigo-600";
const area = "mt-1 w-full rounded border border-slate-800 bg-black px-2 py-1.5 text-[10px] text-slate-200 outline-none focus:border-indigo-600";

function lines(value: string) { return value.split("\n").map(item => item.trim()).filter(Boolean); }
function text(items: string[]) { return items.join("\n"); }
const emptyGabarito: NonNullable<ContentPlanDetails["gabarito"]> = { globalWords: { min: null, ideal: null, max: null }, paragraphRange: { min: null, max: null }, estimatedParagraphs: null, tone: null, depth: null, detail: null, counts: { h2: 0, h3: 0, intro: 1, conclusion: 1, faq: 0, tables: 0, comparisons: 0, checklists: 0, lists: 0, quotes: 0, images: 0, internalLinks: 0, externalLinks: 0, cta: 0, specialBlocks: 0 }, alerts: [], humanDecision: null };

export function PlannerOutlineEditor({ details, onChange }: { details: ContentPlanDetails; onChange: (details: ContentPlanDetails) => void }) {
  const [present, setPresent] = useState(() => clonePlanDetails(details));
  const [past, setPast] = useState<ContentPlanDetails[]>([]);
  const [future, setFuture] = useState<ContentPlanDetails[]>([]);
  const validation = validateOutline(present);
  const apply = (next: ContentPlanDetails) => { setPast(current => [...current.slice(-19), present]); setFuture([]); setPresent(next); onChange(next); };
  const undo = () => { const previous = past.at(-1); if (!previous) return; setPast(current => current.slice(0, -1)); setFuture(current => [present, ...current]); setPresent(previous); onChange(previous); };
  const redo = () => { const next = future[0]; if (!next) return; setFuture(current => current.slice(1)); setPast(current => [...current, present]); setPresent(next); onChange(next); };
  const update = (id: string, patch: Partial<ContentPlanDetails["structure"]["sections"][number]>) => apply(updateOutlineSection(present, id, patch));
  const updateRange = (id: string, field: "wordRange" | "paragraphRange", key: "min" | "ideal" | "max", raw: string) => {
    const section = present.structure.sections.find(item => item.id === id); if (!section) return;
    const current = section[field] || (field === "wordRange" ? { min: null, ideal: null, max: null } : { min: null, max: null });
    const value = raw.trim() ? Math.max(0, Number(raw)) : null;
    apply(updateOutlineSection(present, id, { [field]: { ...current, [key]: value } }));
  };
  const setGabarito = (key: "min" | "ideal" | "max", raw: string) => {
    const current = present.gabarito || emptyGabarito;
    apply({ ...present, gabarito: { ...current, globalWords: { ...current.globalWords, [key]: raw.trim() ? Math.max(0, Number(raw)) : null } } });
  };
  const addBlock = (type: "faq" | "table" | "list" | "comparison" | "checklist") => apply({ ...present, blocks: [...present.blocks, { id: `block:${type}:${present.blocks.length + 1}`, type, sectionId: null, order: present.blocks.length, objective: `Planejar bloco ${type}.`, instructions: [], origin: "human", humanDecision: "Adicionado no editor.", alert: null }] });
  return <div className="space-y-3">
    <div className="flex flex-wrap items-center justify-between gap-2 rounded border border-indigo-900/60 bg-indigo-950/10 p-3"><div><h2 className="text-sm font-black text-white">Editor central de estrutura</h2><p className="text-[10px] text-slate-500">Esqueleto argumentativo; nenhum parágrafo do artigo é escrito aqui.</p></div><div className="flex gap-1"><button className={button} disabled={!past.length} onClick={undo}>Desfazer</button><button className={button} disabled={!future.length} onClick={redo}>Refazer</button><button className={button} onClick={() => apply(addOutlineSection(present, 2))}>Adicionar H2</button><button className={button} onClick={() => apply(addOutlineSection(present, 3))}>Adicionar H3</button></div></div>
    <section className="rounded border border-slate-900 bg-[#0b0c10] p-3"><label className="text-[9px] font-bold uppercase text-slate-500">H1<input className={input} value={present.structure.h1} onChange={event => apply({ ...present, structure: { ...present.structure, h1: event.target.value } })}/></label><div className="mt-3 flex flex-wrap gap-1"><span className="text-[9px] text-slate-600">Adicionar bloco:</span>{(["faq", "table", "list", "comparison", "checklist"] as const).map(type => <button key={type} className={button} onClick={() => addBlock(type)}>{type === "faq" ? "FAQ" : type === "table" ? "Tabela" : type === "list" ? "Lista" : type === "comparison" ? "Comparação" : "Checklist"}</button>)}</div></section>
    <section className="rounded border border-slate-900 bg-[#0b0c10] p-3"><h3 className="text-[10px] font-bold uppercase text-slate-500">Gabarito editável</h3><div className="mt-2 grid gap-2 md:grid-cols-4"><label className="text-[9px] text-slate-500">Palavras mínimas<input className={input} type="number" min="0" value={present.gabarito?.globalWords.min ?? ""} onChange={event => setGabarito("min", event.target.value)}/></label><label className="text-[9px] text-slate-500">Palavras ideais<input className={input} type="number" min="0" value={present.gabarito?.globalWords.ideal ?? ""} onChange={event => setGabarito("ideal", event.target.value)}/></label><label className="text-[9px] text-slate-500">Palavras máximas<input className={input} type="number" min="0" value={present.gabarito?.globalWords.max ?? ""} onChange={event => setGabarito("max", event.target.value)}/></label><label className="text-[9px] text-slate-500">Parágrafos estimados<input className={input} type="number" min="0" value={present.gabarito?.estimatedParagraphs ?? ""} onChange={event => { const current = present.gabarito || emptyGabarito; apply({ ...present, gabarito: { ...current, estimatedParagraphs: event.target.value.trim() ? Number(event.target.value) : null } }); }}/></label></div></section>
    <div className="space-y-2">{present.structure.sections.map((section, index) => <details key={section.id} open={index === 0} className={`rounded border ${validation.orphanH3.includes(section.id) || validation.emptyH2.includes(section.id) ? "border-red-900/70" : "border-slate-900"} bg-[#0b0c10]`}><summary className="flex cursor-pointer list-none items-center gap-2 p-3 text-[11px] font-bold text-slate-200"><span className="rounded bg-indigo-950 px-2 py-0.5 text-indigo-300">H{section.level}</span><span className="min-w-0 flex-1 truncate">{section.decidedHeading || section.heading || "Título pendente"}</span><span className="text-[9px] font-normal text-slate-600">{section.topics.length} tópicos · {section.questions.length} perguntas · {section.entities.length} entidades</span></summary><div className="border-t border-slate-900 p-3"><div className="grid gap-2 md:grid-cols-[90px_minmax(0,1fr)]"><label className="text-[9px] text-slate-500">Nível<select className={input} value={section.level} onChange={event => { const next = Number(event.target.value) as 2 | 3; if (next === 3 && index === 0) return; update(section.id, { level: next }); }}><option value="2">H2</option><option value="3">H3</option></select></label><label className="text-[9px] text-slate-500">Título editorial<input className={input} value={section.decidedHeading || section.heading} onChange={event => update(section.id, { decidedHeading: event.target.value, heading: event.target.value })}/></label></div><div className="mt-2 grid gap-2 md:grid-cols-2"><label className="text-[9px] text-slate-500">Objetivo / função<textarea className={area} rows={2} value={section.objective} onChange={event => update(section.id, { objective: event.target.value, argumentativeFunction: event.target.value })}/></label><label className="text-[9px] text-slate-500">Tópicos incluídos<textarea className={area} rows={2} value={text(section.topics)} onChange={event => update(section.id, { topics: lines(event.target.value) })}/></label><label className="text-[9px] text-slate-500">Perguntas associadas<textarea className={area} rows={2} value={text(section.questions)} onChange={event => update(section.id, { questions: lines(event.target.value) })}/></label><label className="text-[9px] text-slate-500">Entidades e objeções<textarea className={area} rows={2} value={text([...section.entities, ...section.objections])} onChange={event => update(section.id, { entities: lines(event.target.value) })}/></label></div><div className="mt-2 grid gap-2 md:grid-cols-5"><label className="text-[9px] text-slate-500">Palavras min<input className={input} type="number" min="0" value={section.wordRange?.min ?? ""} onChange={event => updateRange(section.id, "wordRange", "min", event.target.value)}/></label><label className="text-[9px] text-slate-500">Palavras ideais<input className={input} type="number" min="0" value={section.wordRange?.ideal ?? ""} onChange={event => updateRange(section.id, "wordRange", "ideal", event.target.value)}/></label><label className="text-[9px] text-slate-500">Palavras máx.<input className={input} type="number" min="0" value={section.wordRange?.max ?? ""} onChange={event => updateRange(section.id, "wordRange", "max", event.target.value)}/></label><label className="text-[9px] text-slate-500">Parágrafos min<input className={input} type="number" min="0" value={section.paragraphRange?.min ?? ""} onChange={event => updateRange(section.id, "paragraphRange", "min", event.target.value)}/></label><label className="text-[9px] text-slate-500">Parágrafos máx.<input className={input} type="number" min="0" value={section.paragraphRange?.max ?? ""} onChange={event => updateRange(section.id, "paragraphRange", "max", event.target.value)}/></label></div><div className="mt-3 flex flex-wrap gap-1"><button className={button} disabled={index === 0} onClick={() => apply(moveOutlineSection(present, section.id, -1))}>Subir</button><button className={button} disabled={index === present.structure.sections.length - 1} onClick={() => apply(moveOutlineSection(present, section.id, 1))}>Descer</button><button className={button} disabled={section.level === 3 && index === 0} onClick={() => update(section.id, { level: section.level === 2 ? 3 : 2 })}>{section.level === 2 ? "Transformar em H3" : "Transformar em H2"}</button><button className={`${button} border-red-900 text-red-300`} onClick={() => apply(removeOutlineSection(present, section.id))}>Remover</button></div>{(section.alerts || []).map(alert => <p key={alert} className="mt-2 text-[10px] text-amber-300">{alert}</p>)}{validation.orphanH3.includes(section.id) && <p className="mt-2 text-[10px] text-red-300">H3 órfão: crie/mova-o para depois de um H2.</p>}</div></details>)}</div>
  </div>;
}
