"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { useSession } from "next-auth/react";
import { VersionedBrandDNASchema } from "@/lib/arquiteto/contracts";
import type { ContentPlan, ContentPlanDetails, VersionEnvelope } from "@/lib/arquiteto/contracts";
import type { PlannerItem } from "@/lib/editorial/operational-flow";
import { contentPlanApprovalIssues } from "@/lib/editorial/operational-flow";
import { useBrand } from "@/components/brand-context";
import { useEditorialPipeline } from "@/components/editorial-pipeline-context";
import { hydratePlanner, UNHYDRATED_REFERENCE } from "@/lib/planejador/hydration";
import { buildCockpitViewModel, findDefinitiveContentPlan, type CockpitStep } from "@/lib/planejador/cockpit-view-model";
import { resolvePlannerPublicationIdentity } from "@/lib/planejador/publication-identity";
import { applyStrategicContext, buildPlannerStrategicContext, selectApprovedBrandDna, type PlannerBrandDnaEnvelope, type PlannerStrategicContext } from "@/lib/planejador/strategic-context";
import { PlannerOutlineEditor } from "./planner-outline-editor";

const button = "inline-flex h-8 items-center justify-center rounded border border-indigo-900 bg-indigo-950/20 px-3 text-[10px] font-bold text-indigo-300 hover:bg-indigo-950/50 disabled:cursor-not-allowed disabled:opacity-40";
const smallButton = "inline-flex h-7 items-center justify-center rounded border border-indigo-900 bg-indigo-950/20 px-2.5 text-[10px] font-bold text-indigo-300 hover:bg-indigo-950/50 disabled:cursor-not-allowed disabled:opacity-40";
const card = "rounded-lg border border-slate-900 bg-[#0b0c10] p-4";
const input = "mt-1 h-8 w-full rounded border border-slate-800 bg-black px-2 text-[10px] text-slate-200 outline-none focus:border-indigo-600 disabled:cursor-not-allowed disabled:opacity-50";
const area = "mt-1 w-full rounded border border-slate-800 bg-black px-2 py-1.5 text-[10px] text-slate-200 outline-none focus:border-indigo-600 disabled:cursor-not-allowed disabled:opacity-50";
const steps: Array<{ id: CockpitStep; label: string; description: string }> = [
  { id: "context", label: "1. Contexto", description: "O que chegou do Radar" },
  { id: "strategy", label: "2. Estratégia", description: "Como a unidade será abordada" },
  { id: "structure", label: "3. Estrutura", description: "Outline e gabarito" },
  { id: "resources", label: "4. Recursos", description: "Perguntas, fontes e links" },
  { id: "review", label: "5. Revisão", description: "Checklist e aprovação" },
];

function findPlan(plans: Record<string, VersionEnvelope<ContentPlan>>, id: string) { return findDefinitiveContentPlan(plans, id); }
function findItem(items: PlannerItem[], plan: VersionEnvelope<ContentPlan>) { return items.find(item => item.contentPlanVersionId === plan.versionId || item.articleId === plan.payload.planning?.editorialUnitId) || null; }
function labelStatus(value: string | null | undefined) { return value === "approved" ? "Aprovado" : value === "needs_review" || value === "awaiting_review" ? "Aguardando revisão" : value === "not_requested" ? "Não solicitado" : value === "collected" ? "Coletado" : value === "absent" ? "Ausente" : value || "Não informado"; }
function radarOrigin(value: "real" | "mock" | "absent") { return value === "real" ? "real" : value === "mock" ? "simulado" : "ausente"; }
function originLabel(value: string) { return value === "observed" ? "Observado" : value === "planner" ? "Recomendação do Planejador" : value === "human" ? "Decisão humana" : "Origem não informada"; }
function itemStatusLabel(value: string) { return value === "pending" ? "Pendente" : value === "accepted" ? "Aceito" : value === "rejected" ? "Rejeitado" : value === "covered" ? "Coberto" : value; }
function alertKindLabel(value: string) { return value === "aviso" ? "Aviso" : value === "pendencia" ? "Pendência" : value === "conflito" ? "Conflito" : value === "bloqueio" ? "Bloqueio" : value; }
function publicationStateLabel(value: string | null | undefined) { return value === "draft" ? "Rascunho" : value === "writing" ? "Em redação" : value === "awaiting_review" ? "Aguardando revisão" : value === "in_review" ? "Em revisão" : value === "approved" ? "Aprovada" : value === "ready_to_export" ? "Pronta para exportar" : value === "queued" ? "Na fila" : value === "exported" ? "Exportada" : value === "published" ? "Publicada" : value || "Não iniciada"; }
function Ref({ item }: { item: ReturnType<typeof hydratePlanner>["primaryKeyword"] }) { return <div><p className="text-[11px] text-slate-200">{item.label === UNHYDRATED_REFERENCE ? "Não foi possível carregar esta informação" : item.label}</p><details className="mt-1 text-[9px] text-slate-600"><summary className="cursor-pointer">Ver detalhes técnicos</summary><p className="mt-1">{item.technical.type} · {item.technical.origin} · versão esperada: {item.technical.expectedVersion || "não informada"}</p><p>{item.technical.reason}</p></details></div>; }
function Layer({ title, value, prominent = false }: { title: string; value: string | null | undefined; prominent?: boolean }) { return <div className={`rounded border border-slate-900 p-3 ${prominent ? "border-indigo-800 bg-indigo-950/10" : ""}`}><p className="text-[9px] font-bold uppercase text-slate-600">{title}</p><p className={`mt-1 text-[11px] ${prominent ? "font-bold text-indigo-200" : "text-slate-300"}`}>{value || "Não informado"}</p></div>; }
function Panel({ title, children, description }: { title: string; children: React.ReactNode; description?: string }) { return <section className={card}><div className="flex flex-wrap items-baseline justify-between gap-2"><h2 className="text-[10px] font-black uppercase tracking-wider text-slate-400">{title}</h2>{description && <p className="text-[9px] text-slate-600">{description}</p>}</div><div className="mt-3">{children}</div></section>; }

export function PlannerCockpitWorkspace({ contentPlanId }: { contentPlanId: string }) {
  const { selectedBrandId } = useBrand(); const pipeline = useEditorialPipeline(); const { data: session } = useSession();
  const plan = useMemo(() => findPlan(pipeline.contentPlans, decodeURIComponent(contentPlanId)), [contentPlanId, pipeline.contentPlans]);
  const item = useMemo(() => plan ? findItem(pipeline.plannerItems, plan) : null, [pipeline.plannerItems, plan]);
  const [step, setStep] = useState<CockpitStep>("context"); const [draft, setDraft] = useState<ContentPlanDetails | null>(null); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false);
  const [brandDna, setBrandDna] = useState<PlannerBrandDnaEnvelope | null>(null); const [brandDnaLoading, setBrandDnaLoading] = useState(false); const [brandDnaError, setBrandDnaError] = useState<string | null>(null); const [selectedContextSourceIds, setSelectedContextSourceIds] = useState<string[]>([]);
  useEffect(() => { if (!plan?.payload.planning) return; const timer = window.setTimeout(() => { const nextDraft = structuredClone(plan.payload.planning!); setDraft(nextDraft); setSelectedContextSourceIds(nextDraft.strategyContext?.sourceRefs.filter(source => !["brand_dna", "legacy_brand"].includes(source.sourceType)).map(source => source.id) || []); setStep("context"); setNotice(""); }, 0); return () => window.clearTimeout(timer); }, [plan?.versionId, plan?.payload.planning]);
  useEffect(() => {
    let cancelled = false;
    if (!selectedBrandId) return;
    void Promise.resolve().then(() => { if (!cancelled) { setBrandDnaLoading(true); setBrandDnaError(null); } return fetch(`/api/marca/brand-dna?brandId=${encodeURIComponent(selectedBrandId)}`, { cache: "no-store" }); }).then(async response => {
      const body = await response.json().catch(() => null) as { versions?: unknown[]; events?: Array<{ versionId: string; status: string }>; activeVersionId?: string | null; error?: string } | null;
      if (!response.ok) throw new Error(body?.error || "O contexto estruturado da marca não está disponível.");
      const versions = (body?.versions || []).map(version => VersionedBrandDNASchema.parse(version));
      const approved = selectApprovedBrandDna({ versions, events: body?.events || [], activeVersionId: body?.activeVersionId, brandId: selectedBrandId });
      if (!cancelled) setBrandDna(approved);
    }).catch(error => { if (!cancelled) { setBrandDna(null); setBrandDnaError(error instanceof Error ? error.message : "O contexto estruturado da marca não está disponível."); } }).finally(() => { if (!cancelled) setBrandDnaLoading(false); });
    return () => { cancelled = true; };
  }, [selectedBrandId]);
  const article = item ? pipeline.articleVersions[item.articleId] || null : null; const silo = item ? pipeline.siloVersions[item.siloId] || null : null; const siloPage = item?.unitType === "silo_page" ? pipeline.siloPageVersions[item.articleId] || null : null;
  const document = item ? Object.values(pipeline.documents).find(candidate => candidate.articleDnaRef.entityId === item.articleId) || null : null; const publication = item ? pipeline.operationalPublications.find(candidate => candidate.articleId === item.articleId) || null : null; const radar = item ? pipeline.radarItems.find(candidate => candidate.id === item.radarItemId || candidate.articleId === item.articleId) || null : null; const legacyBriefing = item ? pipeline.snapshot?.briefings.find(candidate => candidate.id === item.articleId) || null : null; const publicationIdentity = selectedBrandId && item ? resolvePlannerPublicationIdentity({ brandId: selectedBrandId, brandName: pipeline.snapshot?.brand.nome, articleId: item.articleId, article: article?.payload || null, operational: publication, legacyBriefing }) : null;
  const previewPlan = plan && draft ? ({ ...plan, payload: { ...plan.payload, planning: draft } } as VersionEnvelope<ContentPlan>) : plan;
  const hydrated = selectedBrandId && item && previewPlan ? hydratePlanner({ brandId: selectedBrandId, snapshot: pipeline.snapshot, item, plan: previewPlan, article, silo, siloPage, serpRecords: pipeline.serpRecords, serpReviews: pipeline.serpReviews, document, radarHydration: radar?.hydration, publicationIdentity }) : null;
  const approvalIssues = selectedBrandId && previewPlan ? contentPlanApprovalIssues(previewPlan, selectedBrandId) : [];
  const view = item && hydrated && previewPlan ? buildCockpitViewModel({ item, plan: previewPlan, hydration: hydrated, approvalIssues, documentExists: Boolean(document), publicationIdentity }) : null;
  const strategicContext = selectedBrandId && pipeline.snapshot ? buildPlannerStrategicContext({ brandId: selectedBrandId, brand: pipeline.snapshot.brand, brandDna, materials: pipeline.materials, skills: pipeline.skills, prompts: pipeline.prompts, selectedSourceIds: selectedContextSourceIds }) : null;
  if (pipeline.loading && !pipeline.snapshot) return <main className="p-6 text-sm text-slate-500">Carregando cockpit…</main>;
  if (!plan || !item || !draft || !hydrated || !view) return <main className="p-6"><Link className={button} href="/planejador">Voltar ao Planejador</Link><p className="mt-5 text-sm text-amber-300">Não foi possível carregar o plano e a unidade editorial desta marca.</p><details className="mt-2 text-xs text-slate-600"><summary className="cursor-pointer">Ver detalhes técnicos</summary><p className="mt-1">{UNHYDRATED_REFERENCE}: não foi encontrada uma versão definitiva do ContentPlan, ou a unidade/marca ainda não está disponível.</p></details></main>;

  const updateDraft = (patch: Partial<ContentPlanDetails>) => setDraft(current => current ? { ...current, ...patch } : current);
  const updateStrategy = (patch: Partial<ContentPlanDetails["strategy"]>) => setDraft(current => current ? { ...current, strategy: { ...current.strategy, ...patch } } : current);
  const updateCta = (patch: Partial<ContentPlanDetails["cta"]>) => setDraft(current => current ? { ...current, cta: { ...current.cta, ...patch } } : current);
  const applyBrandContext = () => { if (!draft || !strategicContext) return; setDraft(current => current ? applyStrategicContext({ details: current, context: strategicContext, selectedSourceIds: selectedContextSourceIds }) : current); setNotice("Contexto da marca aplicado à cópia de trabalho. Revise as decisões antes de salvar."); };
  const save = async () => { setSaving(true); try { const result = await pipeline.savePlannerPlan(item.id, draft, session?.user?.email || session?.user?.id || "usuario-local"); setNotice(result.created ? "Sucessora salva e aguardando revisão humana." : "Nenhuma mudança material; a versão ativa foi preservada."); } catch (error) { setNotice(error instanceof Error ? error.message : "Não foi possível salvar o plano."); } finally { setSaving(false); } };
  const approve = () => { if (!view.canApprove) { setStep("review"); setNotice(`Não é possível aprovar. Resolva ${view.alertCounts.bloqueios} pendência(s) obrigatória(s).`); return; } pipeline.approvePlannerItems([item.id], session?.user?.email || "human"); setNotice("A aprovação humana foi solicitada para a versão ativa."); };
  const sendWriter = async () => { try { const result = await pipeline.startWriting(item.id); setNotice(`ContentDocument ${result.documentId} disponível no Redator.`); } catch (error) { setNotice(error instanceof Error ? error.message : "Não foi possível enviar ao Redator."); } };
  const goNext = () => { const index = steps.findIndex(current => current.id === step); setStep(steps[Math.min(index + 1, steps.length - 1)].id); };
  const goAction = (target: CockpitStep = view.nextAction.step) => setStep(target);
  return <div className="min-h-screen overflow-auto bg-[#07080b] p-3 text-slate-300"><header className="sticky top-0 z-30 mb-3 border-b border-slate-900 bg-[#07080b]/95 pb-3 backdrop-blur"><div className="flex flex-wrap items-start justify-between gap-3"><div><Link href="/planejador" className="text-[9px] uppercase tracking-wider text-indigo-400">← Planejador</Link><h1 className="mt-1 text-lg font-black text-white">Cockpit editorial · {item.unitType === "silo_page" ? "SiloPage" : "Artigo"}</h1><p className="text-[10px] text-slate-500">{item.title} · ID · v{plan.versionNumber}</p></div><div className="flex flex-wrap gap-1"><button className={button} disabled={saving} onClick={() => void save()}>{saving ? "Salvando…" : "Salvar cópia"}</button><button className={button} onClick={() => setStep("review")}>Validar plano</button><button className={button} disabled={!view.canApprove} onClick={approve}>Aprovar versão</button>{["approved", "sent_writer"].includes(item.state) && <button className={button} onClick={() => void sendWriter()}>{document ? "Abrir no Redator" : "Enviar ao Redator"}</button>}</div></div><div className="mt-3 flex gap-1 overflow-x-auto">{steps.map(current => <button key={current.id} className={`min-w-[145px] rounded border px-3 py-2 text-left ${step === current.id ? "border-indigo-500 bg-indigo-950/30 text-white" : "border-slate-900 text-slate-500"}`} onClick={() => setStep(current.id)}><span className="block text-[10px] font-bold">{current.label}</span><span className="mt-1 block text-[9px]">{current.description}</span></button>)}</div></header>
    {notice && <div className="mb-3 rounded border border-amber-900/50 bg-amber-950/20 p-3 text-[10px] text-amber-300">{notice}</div>}
    <div className="grid gap-3 xl:grid-cols-[minmax(0,1fr)_260px]"><main className="min-w-0 space-y-3">{step === "context" && <ContextStage item={item} hydration={hydrated}/>} {step === "strategy" && <StrategyStage details={draft} hydration={hydrated} strategicContext={strategicContext} brandDnaLoading={brandDnaLoading} brandDnaError={brandDnaError} selectedSourceIds={selectedContextSourceIds} setSelectedSourceIds={setSelectedContextSourceIds} applyBrandContext={applyBrandContext} updateStrategy={updateStrategy} updateCta={updateCta}/>} {step === "structure" && <PlannerOutlineEditor details={draft} onChange={setDraft}/>} {step === "resources" && <ResourcesStage details={draft} hydration={hydrated} identity={view.publicationIdentity!} updateDraft={updateDraft} onVerifyPublication={() => setNotice("As fontes locais foram reconciliadas. Nenhuma publicação ou serviço externo foi acionado.")}/>} {step === "review" && <ReviewStage view={view} plan={plan} hydration={hydrated} document={document} publication={publication} onAction={goAction}/>}<div className="flex justify-between"><button className={smallButton} disabled={step === "context"} onClick={() => setStep(steps[Math.max(steps.findIndex(current => current.id === step) - 1, 0)].id)}>Etapa anterior</button><button className={smallButton} disabled={step === "review"} onClick={goNext}>Próxima etapa</button></div></main><SummaryAside view={view} step={step} onNext={goAction}/></div>
  </div>;
}

function ContextStage({ item, hydration }: { item: PlannerItem; hydration: ReturnType<typeof hydratePlanner> }) { return <div className="grid gap-3 md:grid-cols-2"><Panel title="O que chegou ao Planejador" description="Leitura da origem; decisões ficam na etapa Estratégia."><div className="grid gap-3 sm:grid-cols-2"><Layer title="Unidade" value={item.unitType === "silo_page" ? "SiloPage" : "Artigo"}/><Layer title="Título" value={item.title}/><div><p className="text-[9px] text-slate-600">Keyword principal</p><Ref item={hydration.primaryKeyword}/></div><div><p className="text-[9px] text-slate-600">Silo</p><Ref item={hydration.silo}/></div><div><p className="text-[9px] text-slate-600">ArticleDNA</p><Ref item={hydration.articleDna}/></div><div><p className="text-[9px] text-slate-600">SiloDNA</p><Ref item={hydration.siloDna}/></div></div></Panel><Panel title="Keywords e intenções"><div className="grid gap-2"><Layer title="Secundárias" value={hydration.secondaryKeywords.map(value => value.label).join(" · ") || "Nenhuma keyword secundária recebida."}/><Layer title="Reforços" value={hydration.reinforcementKeywords.map(value => value.label).join(" · ") || "Nenhum reforço recebido."}/><div className="grid gap-2 md:grid-cols-3"><Layer title="Original" value={hydration.observed.intent}/><Layer title="Recomendação" value={hydration.recommendation.intent}/><Layer title="Decisão humana" value={hydration.humanDecision.intent} prominent/></div></div></Panel><Panel title="Radar e SERP"><div className="grid gap-2 md:grid-cols-3"><Layer title="Status" value={`${labelStatus(hydration.radar.status)} · ${radarOrigin(hydration.radar.origin)}`}/><Layer title="Intenção observada" value={hydration.radar.observedIntent}/><Layer title="Conflitos" value={hydration.conflicts.join(" · ") || "Nenhum conflito observado."}/></div>{hydration.radar.questions.length ? <p className="mt-3 text-[10px] text-slate-400">Perguntas observadas: {hydration.radar.questions.join(" · ")}</p> : <p className="mt-3 text-[10px] text-amber-300">A SERP ainda não possui perguntas observadas ou aprovação humana.</p>}</Panel></div>; }

function StrategyStage({ details, hydration, strategicContext, brandDnaLoading, brandDnaError, selectedSourceIds, setSelectedSourceIds, applyBrandContext, updateStrategy, updateCta }: { details: ContentPlanDetails; hydration: ReturnType<typeof hydratePlanner>; strategicContext: PlannerStrategicContext | null; brandDnaLoading: boolean; brandDnaError: string | null; selectedSourceIds: string[]; setSelectedSourceIds: (ids: string[]) => void; applyBrandContext: () => void; updateStrategy: (patch: Partial<ContentPlanDetails["strategy"]>) => void; updateCta: (patch: Partial<ContentPlanDetails["cta"]>) => void }) {
  const toggle = (id: string) => setSelectedSourceIds(selectedSourceIds.includes(id) ? selectedSourceIds.filter(current => current !== id) : [...selectedSourceIds, id]);
  return <div className="grid gap-3 xl:grid-cols-[minmax(0,1fr)_360px]">
    <div className="space-y-3">
      <Panel title="Contexto da marca" description="Selecione o que deseja levar para a cópia de trabalho.">
        {brandDnaLoading && <p className="text-[10px] text-slate-500">Carregando o contexto estruturado da marca…</p>}
        {brandDnaError && <p className="text-[10px] text-amber-300">O BrandDNA estruturado não foi carregado. As informações disponíveis continuam visíveis, sem completar dados ausentes.</p>}
        {strategicContext && <>
          <div className="grid gap-2 sm:grid-cols-2"><Layer title="Marca" value={strategicContext.brandName}/><Layer title="Posicionamento" value={strategicContext.positioning}/><Layer title="Público" value={strategicContext.audience.join(" · ")}/><Layer title="Voz" value={strategicContext.voice.join(" · ") || "Voz ainda não definida"}/></div>
          <p className="mt-3 rounded border border-indigo-900/50 bg-indigo-950/10 p-3 text-[10px] text-indigo-200">{details.strategyContext?.applied ? "O contexto da marca já foi aplicado a esta cópia de trabalho." : "O contexto estratégico da marca ainda não foi aplicado a este plano."}</p>
          <div className="mt-3 grid gap-2">
            {[...strategicContext.materials.map(item => ({ id: item.id, label: `Material · ${item.label}`, purpose: item.purpose, source: item })), ...strategicContext.skills.map(item => ({ id: item.id, label: `Skill · ${item.label}`, purpose: item.purpose, source: item })), ...strategicContext.prompts.map(item => ({ id: item.id, label: `Orientação · ${item.label}`, purpose: item.purpose, source: item }))].map(item => <label key={item.id} className="flex gap-2 rounded border border-slate-900 p-2 text-[10px] text-slate-300"><input type="checkbox" checked={selectedSourceIds.includes(item.id)} onChange={() => toggle(item.id)}/><span><strong>{item.label}</strong><span className="block text-[9px] text-slate-500">{item.purpose}</span></span></label>)}
          </div>
          {!strategicContext.materials.length && !strategicContext.skills.length && !strategicContext.prompts.length && <p className="mt-3 text-[10px] text-slate-500">Nenhum material, Skill ou orientação da marca está disponível para seleção.</p>}
          <button className={`${button} mt-3`} onClick={applyBrandContext}>Usar contexto da marca</button>
          <details className="mt-3 text-[9px] text-slate-600"><summary className="cursor-pointer">Ver voz, restrições e origem</summary><div className="mt-2 space-y-1"><p>Objetivos: {strategicContext.businessObjectives.join(" · ") || "não informados"}</p><p>Restrições: {strategicContext.prohibitedClaims.join(" · ") || "não informadas"}</p><p>Princípios: {strategicContext.editorialPrinciples.join(" · ") || "não informados"}</p><p>Fonte: {strategicContext.brandDnaVersionId ? `BrandDNA aprovado · ${strategicContext.brandDnaVersionId}` : strategicContext.brandDnaStatus === "legacy" ? "Contexto cadastrado da marca" : "não disponível"}</p></div></details>
          {strategicContext.missing.map(message => <p key={message} className="mt-2 text-[10px] text-amber-300">{message}</p>)}
        </>}
      </Panel>
      <Panel title="Decisão humana" description="Campos editáveis da cópia de trabalho."><div className="grid gap-3 md:grid-cols-2"><label className="text-[9px] text-slate-500">Objetivo / promessa<textarea className={area} rows={3} value={details.strategy.promise} onChange={event => updateStrategy({ promise: event.target.value })}/></label><label className="text-[9px] text-slate-500">Ângulo editorial<textarea className={area} rows={3} value={details.strategy.angle} onChange={event => updateStrategy({ angle: event.target.value })}/></label><label className="text-[9px] text-slate-500">Intenção validada<select className={input} value={details.strategy.intentValidation} onChange={event => updateStrategy({ intentValidation: event.target.value as ContentPlanDetails["strategy"]["intentValidation"] })}><option value="pending">Pendente</option><option value="validated">Validada</option><option value="conflict">Conflito</option><option value="insufficient">Insuficiente</option></select></label><label className="text-[9px] text-slate-500">Intenção principal<input className={input} value={details.strategy.primaryIntent} onChange={event => updateStrategy({ primaryIntent: event.target.value })}/></label><label className="text-[9px] text-slate-500 md:col-span-2">Fronteira / exclusões<textarea className={area} rows={3} value={details.strategy.boundary} onChange={event => updateStrategy({ boundary: event.target.value })}/></label><label className="text-[9px] text-slate-500 md:col-span-2">Diferenciais<textarea className={area} rows={2} value={details.strategy.differentiation.join("\n")} onChange={event => updateStrategy({ differentiation: event.target.value.split("\n").map(value => value.trim()).filter(Boolean) })}/></label><label className="text-[9px] text-slate-500">CTA principal<textarea className={area} rows={2} value={details.cta.text} onChange={event => updateCta({ text: event.target.value })}/></label><label className="text-[9px] text-slate-500">Objetivo do CTA<textarea className={area} rows={2} value={details.cta.objective} onChange={event => updateCta({ objective: event.target.value })}/></label></div></Panel>
    </div>
    <Panel title="Separação de camadas"><div className="space-y-2"><Layer title="Observado no Radar" value={hydration.observed.intent}/><Layer title="Recomendado pelo Planejador" value={hydration.recommendation.intent}/><Layer title="Decisão humana" value={details.strategy.primaryIntent} prominent/>{details.strategyContext?.conflicts.map(conflict => <p key={conflict} className="text-[10px] text-amber-300">{conflict}</p>)}</div></Panel>
  </div>;
}

function ResourcesStage({ details, hydration, identity, updateDraft, onVerifyPublication }: { details: ContentPlanDetails; hydration: ReturnType<typeof hydratePlanner>; identity: ReturnType<typeof resolvePlannerPublicationIdentity>; updateDraft: (patch: Partial<ContentPlanDetails>) => void; onVerifyPublication: () => void }) { return <div className="grid gap-3 md:grid-cols-2"><Panel title="Identidade editorial" description={identity.protected ? "Proteção aplicada aos campos estruturais." : "Campos estruturais disponíveis enquanto não há publicação confirmada."}><div className="grid gap-2 sm:grid-cols-2"><Layer title="Situação" value={identity.label} prominent/><Layer title="Marca" value={identity.brandName || identity.brandId}/><Layer title="Keyword principal" value={hydration.primaryKeyword.label}/><Layer title="Slug" value={details.metadata.slug}/><Layer title="Canonical" value={details.metadata.canonical}/><Layer title="URL publicada" value={identity.publishedUrl || "URL não confirmada"}/></div>{identity.state === "unknown" && <><p className="mt-3 text-[10px] text-amber-300">A publicação ainda não foi confirmada. Os campos estruturais permanecerão protegidos.</p><button className={`${smallButton} mt-2`} onClick={onVerifyPublication}>Verificar publicação</button></>}<details className="mt-3 rounded border border-slate-900 p-3 text-[10px] text-slate-400"><summary className="cursor-pointer font-bold text-slate-300">Ver detalhes da proteção</summary><p className="mt-2">{identity.state === "published" ? "Este conteúdo já está publicado. Atualizações editoriais são permitidas, mas keyword principal, slug, canonical, marca e vínculo estrutural permanecem protegidos." : identity.state === "conflict" ? "Existem registros divergentes de publicação. A identidade fica protegida até a reconciliação humana." : identity.state === "unknown" ? "A situação de publicação não foi confirmada. Para evitar sobrescrever um conteúdo existente, a proteção é mantida até a verificação." : "Não há confirmação de publicação nesta origem; os campos podem ser ajustados antes da publicação."}</p>{identity.articleIdentityRef && <p className="mt-2">O ArticleDNA mantém referência da identidade publicada; a fonte canônica continua sendo o registro de publicação.</p>}</details></Panel><Panel title="Perguntas, entidades e objeções"><div className="space-y-2">{[["Perguntas", details.questions], ["Entidades", details.entities], ["Objeções", details.objections]].map(([title, items]) => <div key={title as string} className="rounded border border-slate-900 p-3"><p className="text-[9px] font-bold uppercase text-slate-600">{title as string}</p>{(items as Array<{ text: string; sectionId: string | null; origin: string; status: string }>).length ? <ul className="mt-2 space-y-1 text-[10px]">{(items as Array<{ text: string; sectionId: string | null; origin: string; status: string }>).map(item => <li key={item.text}>{item.text} <span className="text-slate-600">· {item.sectionId ? "associada" : "sem seção"} · {originLabel(item.origin)} · {itemStatusLabel(item.status)}</span></li>)}</ul> : <p className="mt-2 text-[10px] text-slate-500">Nenhum item recebido ou adicionado manualmente.</p>}</div>)}</div></Panel><Panel title="Fontes, links e evidências"><p className="text-[10px] text-slate-500">Nenhuma URL ou fato é inventado. Fontes sem URL permanecem pendências explícitas.</p>{details.sources.length ? details.sources.map((source, index) => <div key={source.id} className="mt-2 rounded border border-slate-900 p-2"><p className="text-[10px] text-slate-300">{source.claim}</p><input className={input} value={source.candidateUrl || ""} placeholder="URL aprovada ou vazio" onChange={event => updateDraft({ sources: details.sources.map((current, currentIndex) => currentIndex === index ? { ...current, candidateUrl: event.target.value.trim() || null, status: event.target.value.trim() ? current.status : "needs_source" } : current) })}/><p className="mt-1 text-[9px] text-amber-300">{source.candidateUrl || "Fonte necessária antes da aprovação"}</p></div>) : <p className="mt-3 text-[10px] text-amber-300">Nenhuma fonte validada. Marque Fonte necessária quando houver claim.</p>}</Panel><Panel title="Imagens, blocos e instruções"><p className="text-[10px] text-slate-500">Geração de imagem não é executada nesta sprint.</p>{details.images.length ? details.images.map((image, index) => <label key={image.id} className="mt-2 block text-[9px] text-slate-500">Texto alternativo<input className={input} value={image.altText || ""} onChange={event => updateDraft({ images: details.images.map((current, currentIndex) => currentIndex === index ? { ...current, altText: event.target.value.trim() || null } : current) })}/></label>) : <p className="mt-2 text-[10px] text-slate-500">Nenhuma imagem planejada.</p>}<p className="mt-3 text-[10px] text-slate-400">{details.blocks.length} bloco(s) · {details.guardianInstructions.length} instrução(ões) do Guardião · {details.skills.skillIds.length} Skill(s)</p></Panel><Panel title="Metadados"><div className="grid gap-2 md:grid-cols-2"><label className="text-[9px] text-slate-500">Slug protegido quando publicado<input className={input} disabled={identity.protected} value={details.metadata.slug} onChange={event => updateDraft({ metadata: { ...details.metadata, slug: event.target.value } })}/></label><label className="text-[9px] text-slate-500">Canonical protegido quando publicado<input className={input} disabled={identity.protected} value={details.metadata.canonical || ""} onChange={event => updateDraft({ metadata: { ...details.metadata, canonical: event.target.value.trim() || null } })}/></label></div></Panel></div>; }
function ReviewStage({ view, plan, hydration, document, publication, onAction }: { view: ReturnType<typeof buildCockpitViewModel>; plan: VersionEnvelope<ContentPlan>; hydration: ReturnType<typeof hydratePlanner>; document: { id: string } | null; publication: { state: string } | null; onAction: (step: CockpitStep) => void }) { return <div className="grid gap-3 xl:grid-cols-[minmax(0,1fr)_320px]"><Panel title="Checklist de revisão" description={`${view.progress}% dos critérios aplicáveis concluídos.`}><div className="h-2 overflow-hidden rounded bg-slate-900"><div className="h-full bg-indigo-500" style={{ width: `${view.progress}%` }}/></div><div className="mt-3 grid gap-2 md:grid-cols-2">{view.criteria.filter(criterion => criterion.applicable).map(criterion => <div key={criterion.id} className={`rounded border p-3 ${criterion.done ? "border-emerald-900/50" : criterion.kind === "bloqueio" ? "border-red-900/60" : "border-amber-900/50"}`}><p className="text-[10px] text-slate-200">{criterion.done ? "✓" : "!"} {criterion.label}</p><button className="mt-1 text-[9px] text-indigo-400" onClick={() => onAction(criterion.step)}>Abrir etapa</button></div>)}</div></Panel><Panel title="Alertas e próxima ação"><div className="rounded border border-indigo-900/50 bg-indigo-950/10 p-3"><p className="text-[9px] font-bold uppercase text-indigo-400">Próxima ação</p><p className="mt-1 text-[11px] font-bold text-indigo-200">{view.nextAction.message}</p></div><div className="mt-3 space-y-2">{view.alerts.map(alert => <p key={`${alert.kind}:${alert.message}`} className={`text-[10px] ${alert.kind === "bloqueio" ? "text-red-300" : alert.kind === "conflito" ? "text-orange-300" : alert.kind === "pendencia" ? "text-amber-300" : "text-slate-400"}`}>{alertKindLabel(alert.kind)}: {alert.message}</p>)}</div></Panel><Panel title="Estados separados"><div className="grid gap-2 md:grid-cols-3"><Layer title="Workflow editorial" value={view.status.workflow}/><Layer title="Publicação" value={view.status.publication}/><Layer title="Transferência" value={view.status.transfer}/></div><p className="mt-3 text-[9px] text-slate-600">ContentPlan {plan.versionNumber} · {document ? "ContentDocument associado" : "ContentDocument ainda não criado"} · publicação {publicationStateLabel(publication?.state)} · Radar {radarOrigin(hydration.radar.origin)}</p></Panel></div>; }

function SummaryAside({ view, step, onNext }: { view: ReturnType<typeof buildCockpitViewModel>; step: CockpitStep; onNext: () => void }) { return <aside className="h-fit rounded-lg border border-indigo-900/50 bg-[#0b0c10] p-4 xl:sticky xl:top-24"><p className="text-[9px] font-bold uppercase tracking-wider text-indigo-400">Resumo do plano</p><p className="mt-2 text-2xl font-black text-white">{view.progress}%</p><div className="mt-2 h-2 overflow-hidden rounded bg-slate-900"><div className="h-full bg-indigo-500" style={{ width: `${view.progress}%` }}/></div><div className="mt-4 grid grid-cols-2 gap-2 text-[10px]"><Metric label="H2" value={view.metrics.h2}/><Metric label="H3" value={view.metrics.h3}/><Metric label="Palavras" value={view.metrics.wordIdeal ?? "—"}/><Metric label="Perguntas" value={`${view.coverage.coveredQuestions}/${view.coverage.questions.length}`}/><Metric label="Links" value={view.details.internalLinks.length}/><Metric label="Fontes" value={view.details.sources.filter(source => source.status === "approved").length}/><Metric label="Imagens" value={view.details.images.length}/><Metric label="Bloqueios" value={view.alertCounts.bloqueios}/></div><div className="mt-4 space-y-1 border-t border-slate-900 pt-3 text-[10px]"><p>Workflow: <strong>{view.status.workflow}</strong></p><p>Publicação: <strong>{view.status.publication}</strong></p><p>Transferência: <strong>{view.status.transfer}</strong></p></div><div className="mt-4 rounded border border-amber-900/50 bg-amber-950/10 p-3"><p className="text-[9px] font-bold uppercase text-amber-400">Próxima ação</p><p className="mt-1 text-[10px] text-amber-200">{view.nextAction.message}</p><button className={`${smallButton} mt-2`} onClick={onNext}>Abrir etapa</button></div><p className="mt-3 text-[9px] text-slate-600">Etapa atual: {steps.find(current => current.id === step)?.label}</p></aside>; }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded border border-slate-900 p-2"><p className="text-[8px] uppercase text-slate-600">{label}</p><p className="mt-1 font-bold text-slate-300">{value}</p></div>; }
